    "src/store/learnerProgressSlice.js": "import { createSlice } from '@reduxjs/toolkit'

const learnerProgressSlice = createSlice({
  name: 'learnerProgress',
  initialState: {
    progressData: [],
    goals: [],
  },
  reducers: {
    addProgress: (state, action) => {
      state.progressData.push(action.payload)
    },
    updateGoalStatus: (state, action) => {
      const { goalId, status } = action.payload
      const goal = state.goals.find(g => g.goalId === goalId)
      if (goal) {
        goal.status = status
      }
    },
    setGoals: (state, action) => {
      state.goals = action.payload
    }
  },
})

export const { addProgress, updateGoalStatus, setGoals } = learnerProgressSlice.actions
export default learnerProgressSlice.reducer",
