    "src/screens/GameSelection.jsx": "import React from 'react'
import { useSelector, useDispatch } from 'react-redux'
import { setGlobalDifficulty, setGameDifficulty } from '../store/gameDifficultySlice'
import Button from '../components/Button'

function GameSelection() {
  const dispatch = useDispatch()
  const currentLevel = useSelector((state) => state.gameDifficulty.currentLevel)
  const gameSettings = useSelector((state) => state.gameDifficulty.gameSettings)

  const handleGlobalDifficultyChange = (level) => {
    dispatch(setGlobalDifficulty(level))
  }

  const handleGameDifficultyChange = (gameId, level) => {
    dispatch(setGameDifficulty({ gameId, level }))
  }

  const games = [
    { id: 'puzzle_adventure', name: 'Puzzle Adventure', description: 'Solve puzzles in a magical world.' },
    { id: 'math_explorer', name: 'Math Explorer', description: 'Explore numbers and equations.' },
    { id: 'story_builder', name: 'Story Builder', description: 'Create your own interactive stories.' },
  ]

  return (
    <div className="p-6 bg-white rounded-lg shadow-md">
      <h1 className="text-4xl font-bold text-gray-800 mb-6">Game Selection</h1>
      <p className="text-lg text-gray-600 mb-8">
        Choose a game and adjust the difficulty level to suit your learning style.
      </p>

      <div className="mb-8">
        <h2 className="text-2xl font-semibold text-gray-700 mb-4">Global Difficulty Setting:</h2>
        <div className="flex space-x-4">
          <Button
            onClick={() => handleGlobalDifficultyChange('easy')}
            className={currentLevel === 'easy' ? 'bg-blue-600' : 'bg-gray-400 hover:bg-gray-500'}
          >
            Easy
          </Button>
          <Button
            onClick={() => handleGlobalDifficultyChange('medium')}
            className={currentLevel === 'medium' ? 'bg-blue-600' : 'bg-gray-400 hover:bg-gray-500'}
          >
            Medium
          </Button>
          <Button
            onClick={() => handleGlobalDifficultyChange('hard')}
            className={currentLevel === 'hard' ? 'bg-blue-600' : 'bg-gray-400 hover:bg-gray-500'}
          >
            Hard
          </Button>
        </div>
        <p className="text-sm text-gray-500 mt-2">Current Global Difficulty: <span className="font-semibold capitalize">{currentLevel}</span></p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {games.map((game) => (
          <div key={game.id} className="bg-blue-50 p-6 rounded-lg shadow-sm border border-blue-200">
            <h3 className="text-xl font-bold text-blue-700 mb-2">{game.name}</h3>
            <p className="text-gray-700 mb-4">{game.description}</p>
            <div className="flex space-x-2 mb-4">
              <Button
                onClick={() => handleGameDifficultyChange(game.id, 'easy')}
                className={gameSettings[game.id] === 'easy' ? 'bg-green-500' : 'bg-gray-300 hover:bg-gray-400 text-gray-800'}
              >
                Easy
              </Button>
              <Button
                onClick={() => handleGameDifficultyChange(game.id, 'medium')}
                className={gameSettings[game.id] === 'medium' ? 'bg-yellow-500' : 'bg-gray-300 hover:bg-gray-400 text-gray-800'}
              >
                Medium
              </Button>
              <Button
                onClick={() => handleGameDifficultyChange(game.id, 'hard')}
                className={gameSettings[game.id] === 'hard' ? 'bg-red-500' : 'bg-gray-300 hover:bg-gray-400 text-gray-800'}
              >
                Hard
              </Button>
            </div>
            <p className="text-sm text-gray-600">
              Game Difficulty: <span className="font-semibold capitalize">{gameSettings[game.id] || currentLevel}</span>
            </p>
            <Button className="mt-4 w-full">Play {game.name}</Button>
          </div>
        ))}
      </div>
    </div>
  )
}

export default GameSelection",
    "src/screens/CodingPuzzle.jsx": "import React, { useState } from 'react'
import TextInput from '../components/TextInput'
import Button from '../components/Button'

function CodingPuzzle() {
  const [code, setCode] = useState('// Write your code here')
  const [output, setOutput] = useState('')
  const [feedback, setFeedback] = useState('')

  const handleCodeChange = (e) => {
    setCode(e.target.value)
  }

  const runCode = () => {
    try {
      const simulatedOutput = `Running code...\nOutput for: ${code.substring(0, 30)}...`
      setOutput(simulatedOutput)
      setFeedback('Code executed successfully! (Simulated)')
    } catch (error) {
      setOutput(`Error: ${error.message}`)
      setFeedback('Error during code execution.')
    }
  }

  return (
    <div className="p-6 bg-white rounded-lg shadow-md">
      <h1 className="text-4xl font-bold text-gray-800 mb-6">Coding Puzzle</h1>
      <p className="text-lg text-gray-600 mb-8">
        Challenge your mind with interactive coding puzzles. Write your solution in the editor below.
      </p>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        <div className="bg-blue-50 p-6 rounded-lg shadow-sm border border-blue-200">
          <h2 className="text-2xl font-semibold text-blue-700 mb-4">Puzzle Description:</h2>
          <p className="text-gray-700 mb-4">
            **Task:** Write a function that takes two numbers and returns their sum.
            Name your function `addNumbers`.
          </p>
          <pre className="bg-gray-100 p-3 rounded-md text-sm text-gray-800">
            <code>
              // Example usage expected:\n
              // addNumbers(5, 3) should return 8
            </code>
          </pre>
        </div>

        <div>
          <h2 className="text-2xl font-semibold text-gray-700 mb-4">Your Code:</h2>
          <textarea
            className="w-full p-4 border border-gray-300 rounded-lg font-mono text-sm resize-y \
                       focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            rows="10"
            value={code}
            onChange={handleCodeChange}
            placeholder="Start coding here..."
          ></textarea>
          <Button onClick={runCode} className="mt-4 w-full">
            Run Code
          </Button>

          {feedback && (
            <div className="mt-6 p-4 bg-green-100 text-green-800 rounded-lg border border-green-200">
              <p className="font-semibold">Feedback:</p>
              <p>{feedback}</p>
            </div>
          )}

          {output && (
            <div className="mt-6 p-4 bg-gray-100 text-gray-800 rounded-lg border border-gray-200">
              <p className="font-semibold">Output:</p>
              <pre className="whitespace-pre-wrap">{output}</pre>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

export default CodingPuzzle",
    "src/screens/CreativeProject.jsx": "import React, { useState } from 'react'
import Button from '../components/Button'
import TextInput from '../components/TextInput'

function CreativeProject() {
  const [projectName, setProjectName] = useState('')
  const [projectDescription, setProjectDescription] = useState('')
  const [codeSnippet, setCodeSnippet] = useState('// Your creative code here')
  const [output, setOutput] = useState('')
  const [projects, setProjects] = useState([])

  const handleSaveProject = () => {
    if (projectName && projectDescription && codeSnippet) {
      const newProject = {
        id: Date.now(),
        name: projectName,
        description: projectDescription,
        code: codeSnippet,
        dateCreated: new Date().toLocaleDateString(),
      }
      setProjects([...projects, newProject])
      alert('Project saved successfully! (Simulated)')
      setProjectName('')
      setProjectDescription('')
      setCodeSnippet('// Your creative code here')
    } else {
      alert('Please fill in all project details.')
    }
  }

  const handleRunCodeSnippet = (code) => {
    try {
      const simulatedOutput = `Executing creative project code...\nResult for: ${code.substring(0, 30)}...`
      setOutput(simulatedOutput)
    } catch (error) {
      setOutput(`Error: ${error.message}`)
    }
  }

  return (
    <div className="p-6 bg-white rounded-lg shadow-md">
      <h1 className="text-4xl font-bold text-gray-800 mb-6">Creative Project Hub</h1>
      <p className="text-lg text-gray-600 mb-8">
        Unleash your creativity! Build interactive stories, design mini-games, or bring your ideas to life with code.
      </p>

      <div className="mb-10 p-6 bg-purple-50 rounded-lg shadow-sm border border-purple-200">
        <h2 className="text-2xl font-semibold text-purple-700 mb-4">Start a New Project</h2>
        <TextInput
          id="projectName"
          label="Project Name"
          value={projectName}
          onChange={(e) => setProjectName(e.target.value)}
          placeholder="e.g., Interactive Storybook"
        />
        <div className="mb-4">
          <label htmlFor="projectDescription" className="block text-gray-700 text-sm font-bold mb-2">
            Project Description
          </label>
          <textarea
            id="projectDescription"
            value={projectDescription}
            onChange={(e) => setProjectDescription(e.target.value)}
            className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight \
                       focus:outline-none focus:ring-2 focus:ring-purple-500 focus:border-transparent resize-y"
            rows="4"
            placeholder="Describe your creative project..."
          ></textarea>
        </div>
        <div className="mb-4">
          <label htmlFor="codeSnippet" className="block text-gray-700 text-sm font-bold mb-2">
            Code Snippet (Optional)
          </label>
          <textarea
            id="codeSnippet"
            value={codeSnippet}
            onChange={(e) => setCodeSnippet(e.target.value)}
            className="w-full p-4 border border-gray-300 rounded-lg font-mono text-sm resize-y \
                       focus:outline-none focus:ring-2 focus:ring-purple-500 focus:border-transparent"
            rows="10"
          ></textarea>
        </div>
        <Button onClick={handleSaveProject} className="bg-purple-600 hover:bg-purple-700 w-full">
          Save Project
        </Button>
      </div>

      <div className="mt-10">
        <h2 className="text-2xl font-semibold text-gray-700 mb-4">Your Saved Projects</h2>
        {projects.length === 0 ? (
          <p className="text-gray-600">No projects saved yet. Start creating!</p>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {projects.map((project) => (
              <div key={project.id} className="bg-white p-6 rounded-lg shadow-md border border-gray-200">
                <h3 className="text-xl font-bold text-gray-800 mb-2">{project.name}</h3>
                <p className="text-gray-700 text-sm mb-4">{project.description}</p>
                <p className="text-gray-500 text-xs">Created on: {project.dateCreated}</p>
                <Button onClick={() => handleRunCodeSnippet(project.code)} className="mt-4 w-full bg-green-500 hover:bg-green-600">
                  Run Project Code
                </Button>
              </div>
            ))}
          </div>
        )}
      </div>

      {output && (
        <div className="mt-8 p-4 bg-gray-100 text-gray-800 rounded-lg border border-gray-200">
          <p className="font-semibold">Code Output:</p>
          <pre className="whitespace-pre-wrap">{output}</pre>
        </div>
      )}
    </div>
  )
}

export default CreativeProject",
    "src/screens/ProgressTracking.jsx": "import React from 'react'
import { Routes, Route } from 'react-router-dom'
import { useSelector } from 'react-redux'
import Sidebar from '../components/Sidebar'

const ProgressOverview = () => {
  const progressData = useSelector((state) => state.learnerProgress.progressData)
  const goals = useSelector((state) => state.learnerProgress.goals)
  const user = useSelector((state) => state.userAuth.user)
  const currentLevel = useSelector((state) => state.gameDifficulty.currentLevel)

  return (
    <div className="p-6">
      <h2 className="text-3xl font-bold text-gray-800 mb-4">Learner Progress Overview</h2>
      <p className="text-lg text-gray-600 mb-6">Welcome, {user?.name || 'Parent/Therapist'}!</p>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
        <div className="bg-blue-50 p-6 rounded-lg shadow-sm border border-blue-200">
          <h3 className="text-xl font-semibold text-blue-700 mb-3">Recent Activities</h3>
          {progressData.length === 0 ? (
            <p className="text-gray-600">No recent activities to display.</p>
          ) : (
            <ul className="list-disc list-inside text-gray-700 space-y-2">
              {progressData.slice(-5).map((item, index) => (
                <li key={index}>
                  Game: {item.gameId}, Score: {item.score}, Date: {item.date}
                </li>
              ))}
            </ul>
          )}
        </div>
        <div className="bg-green-50 p-6 rounded-lg shadow-sm border border-green-200">
          <h3 className="text-xl font-semibold text-green-700 mb-3">Current Goals</h3>
          {goals.length === 0 ? (
            <p className="text-gray-600">No goals set yet.</p>
          ) : (
            <ul className="list-disc list-inside text-gray-700 space-y-2">
              {goals.map((goal) => (
                <li key={goal.goalId}>
                  {goal.description} - <span className={`font-medium ${goal.status === 'completed' ? 'text-green-600' : 'text-orange-600'}`}>{goal.status}</span>
                </li>
              ))}
            </ul>
          )}
        </div>
      </div>

      <div className="bg-purple-50 p-6 rounded-lg shadow-sm border border-purple-200">
        <h3 className="text-xl font-semibold text-purple-700 mb-3">Adaptive Settings</h3>
        <p className="text-gray-700">
          Global Game Difficulty: <span className="font-semibold capitalize">{currentLevel}</span>
        </p>
        <p className="text-gray-700 mt-2">
          (Specific game difficulties can be adjusted on the Game Selection page)
        </p>
      </div>
    </div>
  )
}

const ProgressGoals = () => {
  const goals = useSelector((state) => state.learnerProgress.goals)
  return (
    <div className="p-6">
      <h2 className="text-3xl font-bold text-gray-800 mb-4">Goals Management</h2>
      <p className="text-lg text-gray-600 mb-6">View and update learner goals.</p>
      {goals.length === 0 ? (
        <p className="text-gray-600">No goals set yet. You can set new goals here.</p>
