      {reports.length === 0 ? (
        <p className="text-gray-600">No reports available. Reports will appear here after learner activity.</p>
      ) : (
        <ul className="bg-white p-4 rounded-lg shadow">
          {reports.map((report) => (
            <li key={report.reportId} className="mb-3 p-3 border-b border-gray-100 last:border-b-0">
              <p className="font-semibold text-gray-800">Report for Learner ID: {report.learnerId}</p>
              <p className="text-sm text-gray-600">Summary: {report.summary}</p>
