const ProgressSettings = () => {
  const parentSettings = useSelector((state) => state.dashboard.parentSettings)
  return (
    <div className="p-6">
      <h2 className="text-3xl font-bold text-gray-800 mb-4">Parent/Therapist Settings</h2>
      <p className="text-lg text-gray-600 mb-6">Adjust preferences and notifications.</p>
      <div className="bg-white p-6 rounded-lg shadow">
        <p className="text-gray-700 mb-2">Notification preference: {parentSettings.notifications || 'Email'}</p>
        <p className="text-gray-700">Time zone: {parentSettings.timezone || 'UTC'}</p>
