import React, { useState, useEffect } from 'react'
import { useSelector, useDispatch } from 'react-redux'
import { login, logout } from '../store/userAuthSlice'
import TextInput from '../components/TextInput'
import Button from '../components/Button'

function Profile() {
  const dispatch = useDispatch()
  const isLoggedIn = useSelector((state) => state.userAuth.isLoggedIn)
  const user = useSelector((state) => state.userAuth.user)

  const [username, setUsername] = useState('')
  const [password, setPassword] = useState('')
  const [localUserName, setLocalUserName] = useState('')

  useEffect(() => {
    if (user) {
      setLocalUserName(user.name)
    } else {
      setLocalUserName('')
    }
  }, [user])

  const handleLogin = () => {
    if (username === 'test' && password === 'password') {
      dispatch(login({ id: '1', name: 'Learner One', role: 'learner' }))
      setUsername('')
      setPassword('')
    } else {
      alert('Invalid credentials. Use test/password.')
    }
  }

  const handleLogout = () => {
    dispatch(logout())
  }

  return (
    <div className="p-6 bg-white rounded-lg shadow-md max-w-xl mx-auto">
      <h1 className="text-4xl font-bold text-gray-800 mb-6">User Profile</h1>
      {isLoggedIn ? (
        <div>
          <p className="text-xl text-gray-700 mb-4">
            Welcome back, <span className="font-semibold">{localUserName}</span>!
          </p>
          <p className="text-md text-gray-600 mb-6">
            Here you can view and manage your account details.
            (This section would typically show user info, settings, etc.)
          </p>
          <Button onClick={handleLogout} className="bg-red-500 hover:bg-red-600">
            Logout
          </Button>
        </div>
      ) : (
        <div>
          <p className="text-lg text-gray-600 mb-6">
            Please log in to access your profile and personalized content.
          </p>
          <TextInput
            id="username"
            label="Username"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            placeholder="test"
          />
          <TextInput
            id="password"
            label="Password"
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            placeholder="password"
          />
          <Button onClick={handleLogin} className="w-full mt-4">
            Login
          </Button>
          <p className="text-sm text-gray-500 mt-4 text-center">
            (Use username: `test`, password: `password` for demo)
          </p>
        </div>
      )}
    </div>
  )
}

export default Profile

